// Virtual Memory Transparency: Program's view of memory

// 1. Program assumes its own address space starts at 0x0
struct ProcessContext { /* state */ };
ProcessContext* pcb_start = (ProcessContext*)0x0;

// 2. Program uses standard C pointers (which are Virtual Addresses)
#define CODE_START 0x100000
char* code_ptr = (char*)CODE_START;

// 3. Program assumes linear access:
// OS/MMU invisibly translates VA to possibly non-contiguous Physical Addresses (PA)
code_ptr[0] = 0x90; // NOP instruction
code_ptr[1] = 0x90;

// The program never references a Physical Address directly.
void* heap_block = malloc(4096); // Returns a Virtual Address
*(int*)heap_block = 42;
